INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (79, 1, 'Taint 를 거는 주체 알기', '노드에 **Taint** 를 걸고 Pod 에 **Toleration** 을 줍니다. 이 관계에서 "밀어내는 쪽"은 누구일까요?', '주체가 노드라는 점이 핵심입니다.', NULL, NULL, '[]', 'choice', '["Pod 가 노드를 밀어낸다", "노드가 밀어낸다 (Taint). Pod 는 그 밀어냄을 견딜 수 있다고(Toleration) 면제받을 뿐이다", "Scheduler 가 노드를 지운다", "Service 가 Pod 를 밀어낸다"]', 1, 'Taint 는 "오염 표시", Toleration 은 "내성"이라는 뜻입니다. 일반 Pod 는 Taint 된 노드를 피하고, 맞는 Toleration 이 있는 Pod 만 그 노드 후보가 됩니다. 컨트롤 플레인 노드에는 기본으로 Taint 가 걸려 있어 일반 워크로드가 올라가지 않습니다.', NULL, NULL, NULL, NULL),
  (79, 2, 'Taint effect 알기', '`kubectl taint nodes node1 key=value:NoSchedule` 명령의 `NoSchedule` 은 무엇을 뜻할까요?', 'effect 는 이 Taint 를 견디지 못하는 Pod 에게 무엇을 하는지입니다.', NULL, NULL, '[]', 'choice', '["이미 떠 있는 모든 Pod 를 즉시 삭제한다", "노드를 클러스터에서 제거한다", "노드의 디스크를 비운다", "이 Taint 를 견디지 못하는 **새 Pod 는 그 노드에 스케줄링되지 않는다** (이미 떠 있는 Pod 는 그대로)"]', 3, '`NoSchedule` 은 새 배치만 막고, `PreferNoSchedule` 은 가급적 피하며, `NoExecute` 는 이미 실행 중인 Pod 까지 견디지 못하면 내보냅니다(eviction). 효과에 따라 영향 범위가 다릅니다.', NULL, NULL, NULL, NULL),
  (79, 3, 'Affinity 와 Taint 의 방향 차이', '**NodeAffinity** 와 **Taint/Toleration** 의 방향 차이로 알맞은 것은 무엇일까요?', '한쪽은 끌어당기고, 한쪽은 밀어냅니다.', NULL, NULL, '[]', 'choice', '["Affinity 는 Pod 가 원하는 노드로 **끌리는** 방향이고, Taint 는 노드가 Pod 를 **밀어내는** 방향이다. 전용 노드를 만들 때는 둘을 함께 쓴다", "둘 다 노드가 Pod 를 끌어당긴다", "둘은 같은 기능의 다른 이름이다", "Affinity 는 노드를 삭제한다"]', 0, '특정 노드를 전용으로 쓰려면 Taint 로 다른 Pod 를 밀어내고 Affinity(또는 nodeSelector)로 원하는 Pod 를 끌어옵니다. Toleration 만 주면 "그 노드에 가도 된다"일 뿐 "그 노드에 간다"는 아닙니다.', NULL, NULL, NULL, NULL),
  (79, 4, 'cordon 이 하는 일', '`kubectl cordon node1` 을 실행하면 어떻게 될까요?', '방역선(통제선)을 치는 것에 비유됩니다.', NULL, NULL, '[]', 'choice', '["노드 위의 Pod 가 모두 즉시 삭제된다", "노드가 클러스터에서 제거된다", "노드가 **스케줄링 불가**가 되어 새 Pod 는 배치되지 않지만, 이미 떠 있는 Pod 는 그대로 남는다", "노드의 Taint 가 모두 사라진다"]', 2, 'cordon 은 새 출입만 막습니다. 해제는 `kubectl uncordon` 입니다. 점검 전에 새 Pod 가 들어오지 않게 먼저 막아 두는 용도입니다.', NULL, NULL, NULL, NULL),
  (79, 5, '노드를 점검하러 비우는 순서 놓기', '노드를 재부팅 점검하기 위해 안전하게 비우는 흐름을 **앞에서 뒤**로 놓으세요.', '먼저 막고, 비우고, 작업하고, 풀어 줍니다.', NULL, NULL, '[]', 'order', '["노드를 점검하고 재부팅한다", "`kubectl uncordon` 으로 다시 스케줄링을 허용한다", "`kubectl cordon` 으로 새 Pod 가 들어오지 않게 막는다", "`kubectl drain` 으로 기존 Pod 를 다른 노드로 내보낸다"]', NULL, '**cordon → drain → 작업 → uncordon** 입니다. drain 은 내부적으로 cordon 을 먼저 수행하므로 따로 하지 않아도 되지만, 개념 순서는 "차단 → 비우기"입니다. 비우기 전에 막지 않으면 비우는 동안 새 Pod 가 계속 들어올 수 있습니다.', '[2, 3, 0, 1]', NULL, NULL, NULL),
  (79, 6, 'drain 이 Pod 를 내보내는 방식', '`kubectl drain` 이 Pod 를 내보낼 때 **PodDisruptionBudget(PDB)** 을 존중한다는 말의 의미는 무엇일까요?', '"서비스가 최소 N개는 떠 있어야 한다"는 약속입니다.', NULL, NULL, '[]', 'choice', '["PDB 와 상관없이 즉시 모든 Pod 를 강제 종료한다", "PDB 가 노드를 삭제한다", "PDB 는 drain 과 관련이 없다", "\\"최소 N개는 유지\\"하는 약속을 어기게 되면 퇴거(eviction)를 **미룬다**. Pod 를 일방적으로 죽이는 것이 아니라 정해진 절차를 따른다"]', 3, 'drain 은 Eviction API 를 통해 Pod 를 내보내고, 그 과정에서 PDB 를 지킵니다. 그래서 Pod 가 1개뿐이고 PDB 가 최소 1개를 요구하면 drain 이 계속 멈춰 있을 수 있습니다.', NULL, NULL, NULL, NULL),
  (79, 7, 'drain 에 --ignore-daemonsets 가 필요한 이유', '`kubectl drain node1` 이 DaemonSet Pod 때문에 거절됩니다. `--ignore-daemonsets` 를 붙이는 이유는 무엇일까요?', 'DaemonSet 의 목적을 생각해 보세요.', NULL, NULL, '[]', 'choice', '["DaemonSet Pod 는 삭제할 수 없는 시스템 파일이라서이다", "옵션이 없으면 drain 이 노드를 삭제해서이다", "DaemonSet Pod 는 노드마다 하나씩 있어야 하는 Pod 라서, 내보내도 곧바로 같은 노드에 되살아나므로 drain 대상에서 제외하기 위해서이다", "DaemonSet 은 로그를 쓰지 않아서이다"]', 2, 'DaemonSet 은 로그 수집기나 모니터링 에이전트처럼 모든 노드에 상주해야 하는 Pod 를 보장합니다. drain 으로 비워도 컨트롤러가 다시 만들기 때문에 무시하도록 하는 것입니다.', NULL, NULL, NULL, NULL),
  (79, 8, 'Sidecar 알기', 'Pod 안에서 메인 앱 컨테이너 옆에 붙어 로그 수집, 프록시, 인증서 갱신 같은 **보조 역할**을 하는 컨테이너를 무엇이라고 부를까요?', '오토바이 옆에 다는 보조석에서 온 이름입니다.', NULL, NULL, '[]', 'choice', '["Sidecar 컨테이너", "DaemonSet", "Ingress", "StatefulSet"]', 0, 'Sidecar 는 같은 Pod 안에서 네트워크와 볼륨을 공유하며 메인 컨테이너와 함께 뜨고 함께 종료됩니다. 서비스 메시(Istio)의 프록시도 sidecar 방식이 대표적입니다. 최근에는 initContainers 에 `restartPolicy: Always` 를 주는 공식 방식도 있습니다.', NULL, NULL, NULL, NULL),
  (79, 9, 'Pod 의 의미 알기', 'Pod 의 이름은 "완두콩 꼬투리" 또는 "고래 떼"에서 왔습니다. 이 비유가 가리키는 Pod 의 특징으로 알맞은 것은 무엇일까요?', '함께 움직이는 한 묶음입니다.', NULL, NULL, '[]', 'choice', '["컨테이너마다 서로 다른 노드에 흩어진다", "컨테이너 여러 개가 **한 묶음**으로 같은 노드에 배치되고 네트워크와 볼륨을 공유한다", "Pod 에는 컨테이너를 하나만 넣을 수 있다", "Pod 는 네트워크를 공유하지 않는다"]', 1, '같은 Pod 의 컨테이너는 같은 IP 와 포트 공간을 쓰므로 서로 localhost 로 통신할 수 있습니다. 그래서 강하게 결합된 보조 컨테이너(sidecar)를 같은 Pod 에 넣습니다.', NULL, NULL, NULL, NULL),
  (79, 10, 'Ingress 와 Egress 의 방향', '쿠버네티스에서 **Ingress** 와 **Egress** 의 기준과 방향으로 알맞은 것은 무엇일까요?', '기준은 항상 클러스터(또는 Pod)입니다.', NULL, NULL, '[]', 'choice', '["Ingress 는 나가는 트래픽, Egress 는 들어오는 트래픽이다", "둘 다 클러스터 내부 Pod 사이의 통신만 뜻한다", "Egress 는 별도 리소스로 반드시 만들어야 한다", "Ingress 는 밖에서 클러스터(Pod) **안으로** 들어오는 트래픽, Egress 는 안에서 **밖으로** 나가는 트래픽이다"]', 3, 'NetworkPolicy 는 ingress 와 egress 규칙을 따로 둡니다. "Ingress 리소스"는 외부 HTTP 요청을 Service 로 연결하는 오브젝트로 들어오는 쪽만 다루고, 이름이 같은 Egress 리소스는 없습니다.', NULL, NULL, NULL, NULL),
  (79, 11, 'Ingress 에서 Gateway API 로', 'Ingress 리소스의 후속 규격으로 자리 잡고 있는 것은 무엇일까요?', '"입구"에서 "관문"으로 이름이 바뀝니다.', NULL, NULL, '[]', 'choice', '["Gateway API (Gateway, HTTPRoute 같은 리소스)", "Egress API", "NodePort API", "Sidecar API"]', 0, 'Ingress 리소스는 기능이 동결되었고 Gateway API 가 후속입니다. 역할을 인프라 담당(Gateway)과 앱 담당(HTTPRoute)이 나눠 갖게 설계되어 더 풍부한 라우팅을 표현합니다.', NULL, NULL, NULL, NULL),
  (79, 12, 'NetworkPolicy 의 기본 동작 알기', 'Pod 에 **ingress 를 허용하는 NetworkPolicy 하나**가 적용되었습니다. 그 정책이 허용하지 않은 방향의 트래픽은 어떻게 될까요?', '정책이 선택한 Pod 는 허용 목록 방식으로 동작합니다.', NULL, NULL, '[]', 'choice', '["정책이 없는 방향은 항상 자동 허용된다", "모든 트래픽이 무조건 차단되고 정책은 무효이다", "정책이 선택한 Pod 의 해당 방향에서는 **명시적으로 허용한 것만 통과**하고 나머지는 막힌다 (정책을 지우지 않으면 의도치 않은 차단이 이어진다)", "정책은 로그만 남기고 막지 않는다"]', 2, '정책이 Pod 를 선택하면(`podSelector`) 선언한 `policyTypes`(Ingress/Egress) 방향은 허용 목록이 됩니다. 테스트로 만든 광범위한 정책을 남겨 두어 운영 통신이 끊기는 사고가 흔하니, 정책 변경 후에는 영향 범위를 확인하세요.', NULL, NULL, NULL, NULL);
